/* ------------------------------- QR analysis ------------------------------ */

export function analyzeQrMock(fileName: string): ScanResult {
  const indicators: Indicator[] = [
    {
      severity: "high",
      title: "Collect-money request disguised as payout",
      description:
        "The decoded UPI intent requests money FROM you. A QR code can never send money to you.",
      details:
        "Demo decode: upi://pay?pa=example@upi&pn=Example%20Merchant&am=500.00&cu=INR. Scanning a QR always initiates a debit from your account.",
    },
    {
      severity: "medium",
      title: "Unverified payee name",
      description: "The payee handle does not match a verified merchant record.",
    },
    {
      severity: "medium",
      title: "Pre-filled amount",
      description: "A fixed ₹500 amount is embedded in the code, a common refund/cashback scam pattern.",
    },
  ];
  const score = scoreFrom(indicators, 10);

  return {
    scan_id: newId(),
    input_type: "qr",
    target: fileName,
    created_at: new Date().toISOString(),
    risk_score: score,
    risk_level: riskLevelFromScore(score),
    confidence: 0.86,
    summary: "Demo QR decode resolves to a UPI collect request. Verify the recipient before paying.",
    demo: true,
    indicators,
    recommendations: [
      "Never scan a QR code to *receive* money — QR scans only send money.",
      "Do not enter your UPI PIN for an incoming payment.",
      "Confirm the payee name in your UPI app before approving anything.",
      "Cancel the request if you did not initiate the purchase.",
    ],
    technical_analysis: {
      ...idle,
      qr_engine: "complete",
      url_engine: "not_applicable",
      nlp_engine: "complete",
      threat_intel: "unavailable",
      risk_engine: "complete",
    },
    qr_analysis: {
      qr_type: "UPI",
      decoded_data: "upi://pay?pa=example@upi&pn=Example%20Merchant&am=500.00&cu=INR",
      payee: "Example Merchant",
      upi_id: "example@upi",
      amount: 500,
      currency: "INR",
    },
  };
}

/* ------------------------------ Seeded demo ------------------------------ */

export function seedHistory(): ScanResult[] {
  const samples: ScanResult[] = [
    analyzeUrlMock(DEMO_SCAM_URL),
    analyzeMessageMock(DEMO_SCAM_MESSAGE),
    analyzeUrlMock(DEMO_SAFE_URL),
    analyzeQrMock("upi-refund-qr.png"),
    analyzeMessageMock("Congratulations! You won ₹50,000 in the lucky draw. Claim now, offer expires today."),
    analyzeScreenshotMock("bank-verification.png"),
  ];
  const now = Date.now();
  return samples.map((s, i) => ({
    ...s,
    created_at: new Date(now - (i + 1) * 7 * 3600_000).toISOString(),
  }));
}
